import React, { useEffect, useState } from "react";
import axios from "axios";
import { gapi } from "gapi-script";

const CLIENT_ID = process.env.REACT_APP_CLIENT_ID;
const API_KEY = process.env.REACT_APP_API_KEY;
const SCOPES = process.env.REACT_APP_SCOPES;

function GmailClient() {
  const [emails, setEmails] = useState([]);
  const [spamResults, setSpamResults] = useState({});
  const [user, setUser] = useState(null); // 👤 Store user info

  useEffect(() => {
    function start() {
      gapi.client
        .init({
          apiKey: API_KEY,
          clientId: CLIENT_ID,
          scope: SCOPES,
          discoveryDocs: [
            "https://www.googleapis.com/discovery/v1/apis/gmail/v1/rest",
          ],
        })
        .then(() => {
          console.log("GAPI client initialized");
        })
        .catch((error) => {
          console.error("Error initializing GAPI client", error);
        });
    }

    gapi.load("client:auth2", start);
  }, []);

  const handleLogin = async () => {
    try {
      const authInstance = gapi.auth2.getAuthInstance();
      const googleUser = await authInstance.signIn();
      const profile = googleUser.getBasicProfile();

      setUser({
        name: profile.getName(),
        email: profile.getEmail(),
      });

      console.log("Signed in!", profile.getName());

      if (!gapi.client.gmail) {
        await gapi.client.load("gmail", "v1");
        console.log("Gmail API loaded");
      }

      loadEmails();
    } catch (error) {
      console.error("Error during login or Gmail API loading", error);
    }
  };

  const handleLogout = () => {
    const authInstance = gapi.auth2.getAuthInstance();
    authInstance.disconnect().then(() => {
      console.log("User signed out and disconnected.");
      setEmails([]);
      setSpamResults({});
      setUser(null);
    });
  };

  const loadEmails = async () => {
    if (!gapi.client.gmail || !gapi.client.gmail.users) {
      console.error("Gmail API not loaded yet.");
      return;
    }

    const query = "is:unread"; // Get all unread emails without date restriction

    try {
      const response = await gapi.client.gmail.users.messages.list({
        userId: "me",
        q: query,
      });

      if (response.result.messages) {
        const messages = response.result.messages;
        const emailDetails = await Promise.all(
          messages.map(async (message) => {
            const email = await gapi.client.gmail.users.messages.get({
              userId: "me",
              id: message.id,
              format: "full",
            });
            return email.result;
          })
        );

        setEmails(emailDetails);
      } else {
        setEmails([]);
        console.log("No unread emails found.");
      }
    } catch (error) {
      console.error("Error fetching emails", error);
    }
  };

  const checkSpam = async (emailId, emailBody) => {
    try {
      const res = await axios.post("http://localhost:5000/check_spam", {
        text: emailBody,
      });

      setSpamResults((prevResults) => ({
        ...prevResults,
        [emailId]: res.data,
      }));
    } catch (error) {
      console.error("Error checking spam:", error);
    }
  };

  const markAsRead = async (emailId) => {
    try {
      await gapi.client.gmail.users.messages.modify({
        userId: "me",
        id: emailId,
        removeLabelIds: ["UNREAD"],
      });
      setEmails((prev) => prev.filter((email) => email.id !== emailId));
      console.log("Email marked as read:", emailId);
    } catch (error) {
      console.error("Error marking email as read:", error);
    }
  };

  const deleteEmail = async (emailId) => {
    try {
      await gapi.client.gmail.users.messages.trash({
        userId: "me",
        id: emailId,
      });
      setEmails((prevEmails) =>
        prevEmails.filter((email) => email.id !== emailId)
      );
      console.log("Email moved to trash:", emailId);
    } catch (error) {
      console.error("Error trashing email:", error);
      alert(
        "Failed to delete email: " +
          (error?.result?.error?.message || "Unknown error")
      );
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-100 to-indigo-200 flex">
      {/* Sidebar */}
      <div className="bg-gray-800 text-white w-64 p-6 space-y-6">
        <div className="text-center mb-8">
          {/* Centering and expanding the title */}
          <h2 className="text-4xl font-extrabold text-indigo-400 uppercase tracking-wide">
            Spam Sniffer
          </h2>
        </div>
        <div className="space-y-4">
          <button
            onClick={handleLogin}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-lg shadow-lg transform hover:scale-105 transition-all duration-300"
          >
            Login with Gmail
          </button>
          <button
            onClick={handleLogout}
            className="w-full bg-gray-600 hover:bg-gray-700 text-white py-2 px-4 rounded-lg shadow-lg transform hover:scale-105 transition-all duration-300"
          >
            Logout
          </button>
        </div>
      </div>

      {/* Main content area */}
      <div className="flex-1 p-8">
        {/* Top bar */}
        <div className="flex justify-between items-center mb-6">
          {user && (
            <div className="text-gray-800">
              <p className="font-semibold text-2xl">{user.name}</p>
              <p className="text-gray-500">{user.email}</p>
            </div>
          )}
          <button
            onClick={loadEmails}
            className="bg-green-600 hover:bg-green-700 text-white px-5 py-2 rounded-lg shadow-lg transform hover:scale-105 transition-all"
          >
            Refresh Emails
          </button>
        </div>

        {/* Email Dashboard */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {emails.length > 0 ? (
            emails.map((email) => {
              const spamResult = spamResults[email.id];
              const from = email.payload.headers.find(
                (h) => h.name === "From"
              )?.value;
              const subject = email.payload.headers.find(
                (h) => h.name === "Subject"
              )?.value;

              return (
                <div
                  key={email.id}
                  className="bg-white p-6 rounded-xl shadow-xl hover:shadow-2xl transform hover:scale-105 transition-all duration-300"
                >
                  <h5 className="text-xl font-semibold text-indigo-600 mb-2 hover:text-indigo-700">
                    {from}
                  </h5>
                  <p className="text-lg text-gray-700 mb-4 hover:text-gray-800">
                    <strong>Subject:</strong> {subject}
                  </p>
                  <pre className="text-sm text-gray-800 bg-gray-200 p-3 rounded-md overflow-auto">
                    {email.snippet}
                  </pre>

                  <div className="flex gap-4 mt-4">
                    <button
                      onClick={() => checkSpam(email.id, email.snippet)}
                      className="bg-yellow-500 hover:bg-yellow-600 text-white px-5 py-2 rounded-lg shadow-lg transform hover:scale-105 transition-all duration-300"
                    >
                      Check Spam
                    </button>
                    <button
                      onClick={() => markAsRead(email.id)}
                      className="bg-blue-500 hover:bg-blue-600 text-white px-5 py-2 rounded-lg shadow-lg transform hover:scale-105 transition-all duration-300"
                    >
                      Mark as Read
                    </button>
                    <button
                      onClick={() => deleteEmail(email.id)}
                      className="bg-red-500 hover:bg-red-600 text-white px-5 py-2 rounded-lg shadow-lg transform hover:scale-105 transition-all duration-300"
                    >
                      Delete Email
                    </button>
                  </div>

                  {spamResult && (
                    <div className="mt-4 bg-gray-50 border-l-4 border-yellow-500 p-3 rounded-md">
                      <p>
                        <strong>Spam?</strong>{" "}
                        {spamResult.is_spam ? "✅ Yes" : "❌ No"}
                      </p>
                      <p>
                        <strong>Spam Score:</strong> {spamResult.spam_score}
                      </p>
                      <p>
                        <strong>Type:</strong> {spamResult.description}
                      </p>
                      <p>
                        <strong>Summary:</strong> {spamResult.summary}
                      </p>
                    </div>
                  )}
                </div>
              );
            })
          ) : (
            <p className="text-center text-gray-600 col-span-3">
              No unread emails found.
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

export default GmailClient;
